      return `error: '${args[0]}' is not a valid number`;
    }

    const result = convert(value, args[1], args[3]);
    if (!result.ok) {
      return result.error;
    }
    return `${value} ${result.fromUnit} = ${result.value} ${result.toUnit}`;
  },
